import{_ as a,o as e,c as d,a4 as r}from"./chunks/framework.BybBnFXO.js";const _=JSON.parse('{"title":"GIA 4C 钻石分级","description":"","frontmatter":{"title":"GIA 4C 钻石分级","grading":"diamond-4cs"},"headers":[],"relativePath":"zh/grading/diamond-4cs.md","filePath":"zh/grading/diamond-4cs.md","lastUpdated":1785925441000}'),i={name:"zh/grading/diamond-4cs.md"};function o(l,t,n,h,c,s){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="gia-4c-钻石分级" tabindex="-1">GIA 4C 钻石分级 <a class="header-anchor" href="#gia-4c-钻石分级" aria-label="Permalink to &quot;GIA 4C 钻石分级&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>GIA 于 1953 年确立的全球通用钻石分级标准。四要素——克拉、颜色、 净度、切工——相互独立又联合决定钻石价格。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>克拉 (ct)：1 ct = 0.2 g；1 point = 0.01 ct。重量越大稀有度指数级上升。</li><li>颜色：D–Z 色级，仅指黄/棕色调，从完全无色到浅黄/浅棕。</li><li>净度：FL–I3 十级，10× 放大镜下内含物数量与位置决定。</li><li>切工：Excellent / Very Good / Good / Fair / Poor 五级，比例决定火彩。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>等级</th><th>备注</th></tr></thead><tbody><tr><td>diamond</td><td>D/IF/Excellent</td><td>拍卖级</td></tr><tr><td>sapphire</td><td>Cornflower Blue / Excellent</td><td>彩色宝石单看颜色+切工</td></tr></tbody></table><p><em>详见<a href="./intro.html">分级总览</a>。</em></p>',8)])])}const p=a(i,[["render",o]]);export{_ as __pageData,p as default};
